#!/usr/bin/env python3
import os, pty, sys, time, select, struct, fcntl, termios, signal, json

def main():
    # usage: ptyrec.py <cols> <rows> <outfile> <script.json> -- cmd...
    cols = int(sys.argv[1]); rows = int(sys.argv[2]); out = sys.argv[3]; script = json.loads(sys.argv[4])
    assert sys.argv[5] == '--'
    cmd = sys.argv[6:]
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    data = bytearray()
    t0 = time.time()
    # script: list of [delay_seconds, action, arg] where action in "key","resize"
    idx = 0
    status = None
    while True:
        now = time.time() - t0
        while idx < len(script) and script[idx][0] <= now:
            act = script[idx]
            if act[1] == 'key':
                os.write(fd, act[2].encode('latin1'))
            elif act[1] == 'resize':
                c, r = act[2]
                fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', r, c, 0, 0))
                os.kill(pid, signal.SIGWINCH)
            elif act[1] == 'signal':
                os.kill(pid, getattr(signal, act[2]))
            elif act[1] == 'end':
                idx += 1
                break
            idx += 1
        if idx > 0 and script[idx-1][1] == 'end':
            break
        r, _, _ = select.select([fd], [], [], 0.05)
        if fd in r:
            try:
                chunk = os.read(fd, 65536)
            except OSError:
                break
            if not chunk:
                break
            data += chunk
        wpid, st = os.waitpid(pid, os.WNOHANG)
        if wpid == pid:
            status = st
            # drain
            try:
                while True:
                    r, _, _ = select.select([fd], [], [], 0.2)
                    if not r: break
                    chunk = os.read(fd, 65536)
                    if not chunk: break
                    data += chunk
            except OSError:
                pass
            break
    if status is None:
        try:
            os.kill(pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(pid, 0)
        except Exception: pass
    with open(out, 'wb') as f:
        f.write(bytes(data))
    print("exit status:", status, "bytes:", len(data))

main()
