use ratatui::layout::{Constraint, Direction, Layout, Rect};
fn pattern(vm: u16, n: usize, h: u16, chart_c: Constraint) -> String {
    let area = Rect::new(0, 0, 40, h);
    let mut cs: Vec<Constraint> = (0..n).map(|_| Constraint::Length(1)).collect();
    cs.push(chart_c);
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .vertical_margin(vm)
        .constraints(cs)
        .split(area);
    let mut rows = vec!['_'; h as usize];
    for (i, r) in chunks.iter().enumerate() {
        for y in r.y..r.y + r.height {
            if (y as usize) < rows.len() {
                rows[y as usize] = if i < n { 'H' } else { 'C' };
            }
        }
    }
    // chart rows -> G/A/X pattern per ratatui chart layout
    let chart = chunks[n];
    let ch = chart.height;
    if ch >= 1 {
        let mut y = chart.y + ch - 1;
        let top = chart.y;
        if y > top { rows[y as usize] = 'X'; y -= 1; }
        if y > top { rows[y as usize] = 'A'; y -= 1; }
        if ch == 1 { rows[chart.y as usize] = 'X'; } // single row: label only?
        let _ = y;
        for yy in top..=y { if rows[yy as usize] == 'C' { rows[yy as usize] = 'G'; } }
    }
    rows.into_iter().collect()
}
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let which = args[1].as_str();
    for vm in 0..=2u16 {
        for n in 1..=3usize {
            for h in 1..=7u16 {
                let c = match which {
                    "min0" => Constraint::Min(0),
                    "pct100" => Constraint::Percentage(100),
                    "fill" => Constraint::Fill(1),
                    "min1" => Constraint::Min(1),
                    _ => Constraint::Min(0),
                };
                println!("vm={} n={} h={}: {}", vm, n, h, pattern(vm, n, h, c));
            }
        }
    }
}
