{"command":"cd /workspace && cat > pinger/src/lib.rs <<'EOF'
//! A small library that executes the system `ping` command and parses its
//! output into a stream of [`PingResult`] values.

use std::io::{BufRead, BufReader, Read};
use std::process::{Child, Command, ExitStatus, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::Duration;

use regex::Regex;
use thiserror::Error;

mod linux;

pub use linux::{BusyBoxPinger, LinuxPinger};

/// A single parsed line of ping output.
#[derive(Debug)]
pub enum PingResult {
    /// A reply was received with the given round trip time.
    Pong(Duration, String),
    /// The ping utility reported that a reply has not been received.
    Timeout(String),
    /// A line that could not be interpreted.
    Unknown(String),
    /// The ping process has exited.
    PingExited(ExitStatus, String),
}

/// Options describing how the ping process should be started.
#[derive(Debug, Clone)]
pub struct PingOptions {
    pub target: String,
    pub interval: Duration,
    pub interface: Option<String>,
    pub raw_arguments: Option<Vec<String>>,
    pub ipv6: bool,
}

impl PingOptions {
    pub fn new(target: impl ToString, interval: Duration, interface: Option<String>) -> Self {
        Self {
            target: target.to_string(),
            interval,
            interface,
            raw_arguments: None,
            ipv6: false,
        }
    }

    pub fn with_raw_arguments(mut self, args: Vec<impl ToString>) -> Self {
        self.raw_arguments = Some(args.into_iter().map(|a| a.to_string()).collect());
        self
    }

    pub fn with_ipv6(mut self, ipv6: bool) -> Self {
        self.ipv6 = ipv6;
        self
    }
}

#[derive(Error, Debug)]
pub enum PingCreationError {
    #[error("Could not detect ping. Stderr: {stderr:?}\nStdout: {stdout:?}")]
    UnknownPing {
        stderr: Vec<String>,
        stdout: Vec<String>,
    },
    #[error("Error spawning ping: {0}")]
    SpawnError(#[from] std::io::Error),
}

/// Something that knows how to start a ping process and parse its output.
pub trait Pinger: Send + Sync {
    fn from_options(options: PingOptions) -> Result<Self, PingCreationError>
    where
        Self: Sized;

    fn parse_fn(&self) -> fn(String) -> Option<PingResult>;

    fn ping_args(&self) -> (&str, Vec<String>);

    fn start(&self) -> Result<mpsc::Receiver<PingResult>, PingCreationError> {
        let (tx, rx) = mpsc::channel();
        let (cmd, args) = self.ping_args();
        let parser = self.parse_fn();

        let mut child = run_ping(cmd, args)?;
        let stdout = child.stdout.take().expect("child did not have a handle to stdout");
        let mut stderr = child.stderr.take().expect("child did not have a handle to stderr");

        thread::spawn(move || {
            let reader = BufReader::new(stdout);
            for line in reader.lines().map_while(Result::ok) {
                let result = parser(line);
                if let Some(result) = result {
                    if tx.send(result).is_err() {
                        break;
                    }
                }
            }
            let status = child.wait();
            let mut stderr_output = String::new();
            let _ = stderr.read_to_string(&mut stderr_output);
            if let Ok(status) = status {
                let _ = tx.send(PingResult::PingExited(status, stderr_output));
            }
        });

        Ok(rx)
    }
}

fn base_command(cmd: &str) -> Command {
    let mut command = Command::new(cmd);
    command.env("LANG", "C").env("LC_ALL", "C");
    command
}

fn run_ping(cmd: &str, args: Vec<String>) -> Result<Child, PingCreationError> {
    base_command(cmd)
        .args(&args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .stdin(Stdio::null())
        .spawn()
        .map_err(PingCreationError::SpawnError)
}

fn extract_regex(regex: &Regex, line: String) -> Option<PingResult> {
    let cap = regex.captures(&line)?;
    let ms = cap
        .name("ms")
