//!
//! The widget renders a set of datasets as lines (or dots) on a braille/dot
//! canvas, with a labelled y axis on the left and a labelled x axis at the
//! bottom.

use std::cmp::max;

use ratatui::buffer::Buffer;
use ratatui::layout::{Alignment, Rect};
use ratatui::style::{Color, Style};
use ratatui::text::Line;
use ratatui::widgets::Widget;

/// How individual points are drawn.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Marker {
    Braille,
    Dot,
}

/// A single series of `(x, y)` points.
#[derive(Debug, Clone)]
pub struct Dataset<'a> {
