    pub datasets: Vec<Dataset<'a>>,
    pub x_bounds: [f64; 2],
    pub y_bounds: [f64; 2],
    pub x_labels: Vec<Line<'a>>,
    pub y_labels: Vec<Line<'a>>,
    pub axis_style: Style,
}

struct ChartLayout {
    label_x: Option<u16>,
    label_y: Option<u16>,
    axis_x: Option<u16>,
    axis_y: Option<u16>,
    graph_area: Rect,
}

impl<'a> Chart<'a> {
    fn layout(&self, area: Rect) -> Option<ChartLayout> {
        if area.height == 0 || area.width == 0 {
            return None;
        }
        let mut x = area.left();
        let mut y = area.bottom() - 1;

        let mut label_x = None;
        if !self.x_labels.is_empty() && y > area.top() {
            label_x = Some(y);
            y -= 1;
        }

        let label_y = if self.y_labels.is_empty() { None } else { Some(x) };
        x += self.max_width_of_labels_left_of_y_axis(area, !self.y_labels.is_empty());

        let mut axis_x = None;
        if !self.x_labels.is_empty() && y > area.top() {
            axis_x = Some(y);
            y -= 1;
        }

        let mut axis_y = None;
        if !self.y_labels.is_empty() && x + 1 < area.right() {
            axis_y = Some(x);
            x += 1;
        }

        let graph_width = area.right().saturating_sub(x);
        let graph_height = y.saturating_sub(area.top()).saturating_add(1);
        let graph_area = Rect::new(x, area.top(), graph_width, graph_height);

        Some(ChartLayout {
            label_x,
            label_y,
            axis_x,
            axis_y,
            graph_area,
        })
    }

    fn max_width_of_labels_left_of_y_axis(&self, area: Rect, has_y_axis: bool) -> u16 {
        let mut max_width = self
            .y_labels
            .iter()
            .map(Line::width)
            .max()
            .unwrap_or_default() as u16;

        if let Some(first_x_label) = self.x_labels.first() {
            let first_label_width = first_x_label.width() as u16;
            // x labels are left aligned: the last character of the first label
            // sits below the y axis rather than left of it.
            let y_axis_offset = u16::from(has_y_axis);
            let width_left_of_y_axis = first_label_width.saturating_sub(y_axis_offset);
            max_width = max(max_width, width_left_of_y_axis);
        }
        // labels can take at most a third of the total width
        max_width.min(area.width / 3)
    }

    fn render_label(buf: &mut Buffer, label: &Line, label_area: Rect, alignment: Alignment) {
        let label = match alignment {
            Alignment::Left => label.clone().left_aligned(),
            Alignment::Center => label.clone().centered(),
            Alignment::Right => label.clone().right_aligned(),
        };
        label.render(label_area, buf);
    }

    fn render_x_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let Some(y) = layout.label_x else { return };
        let labels = &self.x_labels;
        let labels_len = labels.len() as u16;
        if labels_len < 2 {
            return;
        }

        let width_between_ticks = graph_area.width / labels_len;

        // first label: right aligned in the space left of the graph area
        let label_area = Rect::new(chart_area.left(), y, graph_area.left() - chart_area.left(), 1);
        Self::render_label(buf, labels.first().unwrap(), label_area, Alignment::Right);

        for (i, label) in labels[1..labels.len() - 1].iter().enumerate() {
            let x = graph_area.left() + (i + 1) as u16 * width_between_ticks + 1;
            let label_area = Rect::new(x, y, width_between_ticks.saturating_sub(1), 1);
            Self::render_label(buf, label, label_area, Alignment::Center);
        }

        let x = graph_area.right() - width_between_ticks;
        let label_area = Rect::new(x, y, width_between_ticks, 1);
        Self::render_label(buf, labels.last().unwrap(), label_area, Alignment::Right);
    }

    fn render_y_labels(&self, buf: &mut Buffer, layout: &ChartLayout, chart_area: Rect, graph_area: Rect) {
        let Some(x) = layout.label_y else { return };
        let labels = &self.y_labels;
        let labels_len = labels.len() as u16;
        if labels_len < 2 {
            return;
        }

        for (i, label) in labels.iter().enumerate() {
            let dy = i as u16 * (graph_area.height - 1) / (labels_len - 1);
            if dy < graph_area.bottom() {
                let label_area = Rect::new(
                    x,
                    graph_area.bottom().saturating_sub(1) - dy,
                    (graph_area.left() - chart_area.left()).saturating_sub(1),
                    1,
                );
                Self::render_label(buf, label, label_area, Alignment::Left);
            }
        }
    }
}

impl Widget for Chart<'_> {
    fn render(self, area: Rect, buf: &mut Buffer) {
        let Some(layout) = self.layout(area) else {
            return;
        };
        let graph_area = layout.graph_area;

        self.render_x_labels(buf, &layout, area, graph_area);
        self.render_y_labels(buf, &layout, area, graph_area);

        if let Some(y) = layout.axis_x {
            for x in graph_area.left()..graph_area.right() {
                buf[(x, y)].set_symbol("─").set_style(self.axis_style);
            }
        }

        if let Some(x) = layout.axis_y {
            for y in graph_area.top()..graph_area.bottom() {
                buf[(x, y)].set_symbol("│").set_style(self.axis_style);
            }
        }

        if let (Some(y), Some(x)) = (layout.axis_x, layout.axis_y) {
            buf[(x, y)].set_symbol("└").set_style(self.axis_style);
        }

        if graph_area.width == 0 || graph_area.height == 0 {
            return;
        }

        buf.set_style(graph_area, Style::default().bg(Color::Reset));

        let mut layers: Vec<Layer> = Vec::new();
        for dataset in &self.datasets {
            let mut grid = Grid::new(graph_area.width, graph_area.height, dataset.marker);
            let mut painter = Painter {
                grid: &mut grid,
                x_bounds: self.x_bounds,
                y_bounds: self.y_bounds,
            };
            for (x, y) in dataset.data {
                if let Some((px, py)) = painter.get_point(*x, *y) {
                    painter.grid.paint(px, py, dataset.color);
                }
            }
            for pair in dataset.data.windows(2) {
                painter.draw_line(pair[0].0, pair[0].1, pair[1].0, pair[1].1, dataset.color);
            }
            if painter.grid.dirty {
                layers.push(grid.save());
            }
        }

        let width = graph_area.width as usize;
        for layer in layers {
            for (index, (symbol, color)) in layer.cells.into_iter().enumerate() {
                let Some(symbol) = symbol else { continue };
                let (x, y) = (
                    (index % width) as u16 + graph_area.left(),
                    (index / width) as u16 + graph_area.top(),
                );
                buf[(x, y)].set_char(symbol).set_fg(color).set_bg(Color::Reset);
            }
        }
    }
}

const BRAILLE_DOTS: [[u16; 2]; 4] = [
    [0x0001, 0x0008],
    [0x0002, 0x0010],
    [0x0004, 0x0020],
    [0x0040, 0x0080],
];

struct Layer {
    cells: Vec<(Option<char>, Color)>,
}

struct Grid {
    marker: Marker,
    width: u16,
    height: u16,
    patterns: Vec<u16>,
    colors: Vec<Color>,
    dirty: bool,
}

impl Grid {
    fn new(width: u16, height: u16, marker: Marker) -> Self {
        let len = width as usize * height as usize;
        Self {
            marker,
            width,
            height,
            patterns: vec![0; len],
            colors: vec![Color::Reset; len],
            dirty: false,
        }
    }

    fn resolution(&self) -> (f64, f64) {
        match self.marker {
            Marker::Braille => (f64::from(self.width) * 2.0, f64::from(self.height) * 4.0),
            Marker::Dot => (f64::from(self.width), f64::from(self.height)),
        }
    }

    fn paint(&mut self, x: usize, y: usize, color: Color) {
        self.dirty = true;
        match self.marker {
            Marker::Braille => {
                let index = y / 4 * self.width as usize + x / 2;
                if let Some(p) = self.patterns.get_mut(index) {
                    *p |= BRAILLE_DOTS[y % 4][x % 2];
                }
                if let Some(c) = self.colors.get_mut(index) {
                    *c = color;
                }
            }
            Marker::Dot => {
                let index = y * self.width as usize + x;
                if let Some(p) = self.patterns.get_mut(index) {
                    *p = 1;
                }
                if let Some(c) = self.colors.get_mut(index) {
                    *c = color;
                }
            }
        }
    }

    fn save(&self) -> Layer {
        let cells = self
            .patterns
            .iter()
            .zip(self.colors.iter())
            .map(|(p, c)| {
                let symbol = match self.marker {
                    Marker::Braille => {
                        if *p == 0 {
                            None
                        } else {
                            char::from_u32(0x2800 + *p as u32)
                        }
                    }
                    Marker::Dot => {
                        if *p == 0 {
                            None
                        } else {
                            Some('•')
                        }
                    }
                };
                (symbol, *c)
            })
            .collect();
        Layer { cells }
    }
}

struct Painter<'g> {
    grid: &'g mut Grid,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
}

impl Painter<'_> {
    fn get_point(&self, x: f64, y: f64) -> Option<(usize, usize)> {
        let left = self.x_bounds[0];
        let right = self.x_bounds[1];
        let top = self.y_bounds[1];
        let bottom = self.y_bounds[0];
        if x < left || x > right || y < bottom || y > top {
            return None;
        }
        let width = (right - left).abs();
        let height = (top - bottom).abs();
        if width == 0.0 || height == 0.0 {
            return None;
        }
        let (res_x, res_y) = self.grid.resolution();
        let px = ((x - left) * (res_x - 1.0) / width) as usize;
        let py = ((top - y) * (res_y - 1.0) / height) as usize;
        Some((px, py))
    }

    fn draw_line(&mut self, x1: f64, y1: f64, x2: f64, y2: f64, color: Color) {
        let Some((x1, y1)) = self.get_point(x1, y1) else { return };
        let Some((x2, y2)) = self.get_point(x2, y2) else { return };
        let (dx, dy) = (x1.abs_diff(x2), y1.abs_diff(y2));
        if dx == 0 {
            for y in y1.min(y2)..=y1.max(y2) {
                self.grid.paint(x1, y, color);
            }
        } else if dy == 0 {
            for x in x1.min(x2)..=x1.max(x2) {
                self.grid.paint(x, y1, color);
            }
        } else if dy < dx {
            if x1 > x2 {
                self.draw_line_low(x2, y2, x1, y1, color);
            } else {
                self.draw_line_low(x1, y1, x2, y2, color);
            }
        } else if y1 > y2 {
            self.draw_line_high(x2, y2, x1, y1, color);
        } else {
            self.draw_line_high(x1, y1, x2, y2, color);
        }
    }

    fn draw_line_low(&mut self, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
        let dx = (x2 - x1) as isize;
        let dy = (y2 as isize - y1 as isize).abs();
        let mut d = 2 * dy - dx;
        let mut y = y1;
        for x in x1..=x2 {
            self.grid.paint(x, y, color);
            if d > 0 {
                y = if y1 > y2 { y.saturating_sub(1) } else { y.saturating_add(1) };
                d -= 2 * dx;
            }
            d += 2 * dy;
        }
    }

    fn draw_line_high(&mut self, x1: usize, y1: usize, x2: usize, y2: usize, color: Color) {
        let dx = (x2 as isize - x1 as isize).abs();
        let dy = (y2 - y1) as isize;
        let mut d = 2 * dx - dy;
        let mut x = x1;
        for y in y1..=y2 {
            self.grid.paint(x, y, color);
            if d > 0 {
                x = if x1 > x2 { x.saturating_sub(1) } else { x.saturating_add(1) };
                d -= 2 * dy;
            }
            d += 2 * dx;
        }
    }
}
