//! Storage and summary statistics for a single graph entry (a host or a command).

use std::time::Duration;

use anyhow::anyhow;
use chrono::prelude::*;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::Style;
use ratatui::text::Span;
use ratatui::widgets::{Paragraph, Widget};

use crate::chart::Marker;

pub struct PlotData {
    pub display: String,
    pub data: Vec<(f64, f64)>,
    pub style: Style,
    buffer: chrono::Duration,
    simple_graphics: bool,
}

impl PlotData {
    pub fn new(display: String, buffer: u64, style: Style, simple_graphics: bool) -> PlotData {
        PlotData {
            display,
            data: Vec::with_capacity(150),
            buffer: chrono::Duration::try_seconds(buffer as i64)
                .ok_or_else(|| anyhow!("Error converting {} to seconds", buffer))
                .unwrap(),
            style,
            simple_graphics,
        }
    }

    pub fn marker(&self) -> Marker {
        if self.simple_graphics {
            Marker::Dot
        } else {
            Marker::Braille
        }
    }

    /// Record a new sample. `None` represents a timeout (or a failed command).
    pub fn update(&mut self, item: Option<Duration>) {
        let now = Local::now();
        let idx = now.timestamp_millis() as f64 / 1000f64;
        match item {
            Some(dur) => self.data.push((idx, dur.as_micros() as f64)),
            None => self.data.push((idx, f64::NAN)),
        }
        // Drop everything that fell out of the display window, apart from the
        // most recent of those points so lines can still enter from the left.
        let earliest_timestamp = (now - self.buffer).timestamp_millis() as f64 / 1000f64;
        let last_idx = self
            .data
            .iter()
            .enumerate()
            .filter(|(_, (timestamp, _))| *timestamp < earliest_timestamp)
            .map(|(idx, _)| idx)
            .last();
        if let Some(idx) = last_idx {
            self.data.drain(0..idx).for_each(drop);
        }
    }

    fn stats(&self) -> Option<Vec<String>> {
        let ping_header = self.display.clone();
        let values: Vec<f64> = self
            .data
            .iter()
            .filter(|(_, v)| !v.is_nan())
            .map(|(_, v)| *v)
            .collect();
        if values.is_empty() {
            return None;
        }

        let timeouts = self.data.iter().filter(|(_, v)| v.is_nan()).count();
        let last = self.data.last().map(|(_, v)| *v).unwrap_or(f64::NAN);

        let mut sorted = values.clone();
        sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let min = sorted[0];
        let max = sorted[sorted.len() - 1];
        let avg = sorted.iter().sum::<f64>() / sorted.len() as f64;
        // Jitter: the average spread between consecutive (sorted) samples.
        let jitter = sorted
            .windows(2)
            .map(|w| (w[1] - w[0]).abs())
            .sum::<f64>()
            / (sorted.len() - 1) as f64;
        let p95_idx = (sorted.len() as f64 * 0.95).round() as usize;
        let p95 = sorted.get(p95_idx).copied().unwrap_or(0f64);

        let _ = ping_header;
        Some(vec![
            format!("last {:?}", micros(last)),
            format!("min {:?}", micros(min)),
            format!("max {:?}", micros(max)),
            format!("avg {:?}", micros(avg)),
            format!("jtr {:?}", micros(jitter)),
            format!("p95 {:?}", micros(p95)),
            format!("t/o {}", timeouts),
        ])
    }

    /// Render the one line summary for this entry into `area`.
    pub fn render_header(&self, area: Rect, buf: &mut ratatui::buffer::Buffer) {
        let chunks = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([
                Constraint::Percentage(30),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
                Constraint::Percentage(10),
            ])
            .split(area);

        Paragraph::new(Span::raw(self.display.clone()))
            .style(self.style)
            .render(chunks[0], buf);

        if let Some(stats) = self.stats() {
            for (text, chunk) in stats.into_iter().zip(chunks.iter().skip(1)) {
                Paragraph::new(Span::raw(text))
                    .style(self.style)
                    .render(*chunk, buf);
            }
        }
    }
}

fn micros(value: f64) -> Duration {
    Duration::from_micros(value as u64)
}
