            .timestamp_millis_opt((bounds[1] * 1000f64) as i64)
            .single()
            .unwrap_or_else(Local::now);
        let diff = (upper - lower) / 2;
        let midpoint = lower + diff;
        vec![
            Line::from(lower.time().to_string()),
            Line::from(midpoint.time().to_string()),
            Line::from(upper.time().to_string()),
        ]
    }
}

/// Spawn a thread that repeatedly runs `cmd` and reports how long it takes.
fn start_cmd_thread(
    watch_cmd: &str,
    host_id: usize,
    watch_interval: Duration,
    cmd_tx: Sender<Event>,
    kill_event: Arc<AtomicBool>,
) -> thread::JoinHandle<Result<()>> {
    let mut words = watch_cmd.split_whitespace();
    let cmd = words
        .next()
        .expect("Must specify a command to watch")
        .to_string();
    let cmd_args: Vec<String> = words.map(str::to_string).collect();

    thread::spawn(move || -> Result<()> {
        while !kill_event.load(Ordering::Acquire) {
            let start = Instant::now();
            let output = Command::new(&cmd)
                .args(&cmd_args)
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status();
            let duration = start.elapsed();
            let result = match output {
                Ok(status) if status.success() => Some(duration),
                _ => None,
            };
            cmd_tx.send(Event::Update(host_id, result))?;
            thread::sleep(watch_interval);
        }
        Ok(())
    })
}

/// Spawn the ping process for `host` and forward its results to the main loop.
fn start_ping_thread(
    host: &str,
    host_id: usize,
    watch_interval: Duration,
    ping_tx: Sender<Event>,
    kill_event: Arc<AtomicBool>,
    interface: Option<String>,
    ping_args: &[String],
    ipv6: bool,
) -> Result<thread::JoinHandle<Result<()>>> {
    let mut options = PingOptions::new(host, watch_interval, interface).with_ipv6(ipv6);
    if !ping_args.is_empty() {
        options = options.with_raw_arguments(ping_args.to_vec());
    }
    let stream = ping(options)?;
    Ok(thread::spawn(move || -> Result<()> {
        while !kill_event.load(Ordering::Acquire) {
            match stream.recv() {
                Ok(PingResult::Pong(duration, _)) => {
                    ping_tx.send(Event::Update(host_id, Some(duration)))?;
                }
                Ok(PingResult::Timeout(_)) => {
                    ping_tx.send(Event::Update(host_id, None))?;
                }
                Ok(PingResult::Unknown(_)) => {}
                Ok(PingResult::PingExited(status, stderr)) => {
                    if !status.success() {
                        eprintln!(
                            "There was an error running ping: {}\nStderr: {}\n",
                            status, stderr
                        );
                    }
                    ping_tx.send(Event::Exit)?;
                    break;
                }
                Err(_) => break,
            }
        }
        Ok(())
    }))
}

fn resolve(host: &str, ipv4: bool, ipv6: bool) -> Result<IpAddr> {
    let addrs: Vec<IpAddr> = (host, 0)
        .to_socket_addrs()
        .with_context(|| format!("Resolving {}", host))?
        .map(|a| a.ip())
        .collect();
    let picked = if ipv4 {
        addrs.into_iter().find(IpAddr::is_ipv4)
    } else if ipv6 {
        addrs.into_iter().find(IpAddr::is_ipv6)
    } else {
        addrs.into_iter().next()
    };
    match picked {
        Some(ip) => Ok(ip),
        None if ipv4 => bail!("Could not resolve '{}' to IPv4", host),
        None if ipv6 => bail!("Could not resolve '{}' to IPv6", host),
        None => bail!("Could not resolve '{}'", host),
    }
}

fn is_quit(key: &KeyEvent) -> bool {
    match key.code {
        KeyCode::Char('q') | KeyCode::Esc => true,
        KeyCode::Char('c') => key.modifiers.contains(KeyModifiers::CONTROL),
        _ => false,
    }
}

fn render(frame: &mut Frame, app: &App, vertical_margin: u16, horizontal_margin: u16) {
    let mut constraints: Vec<Constraint> = app.data.iter().map(|_| Constraint::Length(1)).collect();
    constraints.push(Constraint::Min(0));
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .vertical_margin(vertical_margin)
        .horizontal_margin(horizontal_margin)
        .constraints(constraints)
        .split(frame.area());

    for (plot, chunk) in app.data.iter().zip(chunks.iter()) {
        plot.render_header(*chunk, frame.buffer_mut());
    }

    let datasets: Vec<Dataset> = app
        .data
        .iter()
        .map(|d| Dataset {
            data: d.data.as_slice(),
            color: d.style.fg.unwrap_or(Color::Reset),
            marker: d.marker(),
        })
        .collect();

    let y_axis_bounds = app.y_axis_bounds();
    let x_axis_bounds = app.x_axis_bounds();

    let chart = Chart {
        datasets,
        x_bounds: x_axis_bounds,
        y_bounds: y_axis_bounds,
        x_labels: app.x_axis_labels(x_axis_bounds),
        y_labels: app.y_axis_labels(y_axis_bounds),
        axis_style: Style::default().fg(Color::Gray),
    };
    frame.render_widget(chart, chunks[app.data.len()]);
}

fn main() -> Result<()> {
    let args = Args::parse();

    if args.hosts_or_commands.is_empty() {
        bail!("At least one host or command must be given (i.e gping google.com). Use --help for a full list of arguments.");
    }

    let colors = parse_colors(&args.color_codes)?;

    let hosts_or_commands: Vec<String> = args
        .hosts_or_commands
        .iter()
        .map(|h| try_host_from_cloud_region(h))
        .collect();

    let watch_interval = Duration::from_millis(
        (args.watch_interval.unwrap_or(if args.cmd { 0.5 } else { 0.2 }) * 1000.0) as u64,
    );

    let (key_tx, rx) = mpsc::channel();
    let kill_event = Arc::new(AtomicBool::new(false));
    let mut threads = Vec::new();
    let mut data = Vec::new();

    let color_for = |idx: usize| -> Color {
        colors
            .get(idx)
            .copied()
            .unwrap_or_else(|| default_color(idx - colors.len()))
    };

    if args.cmd {
        for (host_id, cmd) in hosts_or_commands.iter().enumerate() {
            data.push(PlotData::new(
                cmd.to_string(),
                args.buffer,
                Style::default().fg(color_for(host_id)),
                args.simple_graphics,
            ));
            threads.push(start_cmd_thread(
                cmd,
                host_id,
                watch_interval,
                key_tx.clone(),
                kill_event.clone(),
            ));
        }
    } else {
        let mut resolved = Vec::with_capacity(hosts_or_commands.len());
        for host in &hosts_or_commands {
            let ip = resolve(host, args.ipv4, args.ipv6)?;
            resolved.push((host.clone(), ip));
        }
        for (host_id, (host, ip)) in resolved.into_iter().enumerate() {
            data.push(PlotData::new(
                format!("{} ({})", host, ip),
                args.buffer,
                Style::default().fg(color_for(host_id)),
                args.simple_graphics,
            ));
            let ipv6 = args.ipv6 || host.parse::<Ipv6Addr>().is_ok();
            threads.push(start_ping_thread(
                &host,
                host_id,
                watch_interval,
                key_tx.clone(),
                kill_event.clone(),
                args.interface.clone(),
                &args.ping_args,
                ipv6,
            )?);
        }
    }

    let mut app = App::new(data, Duration::from_secs(args.buffer));

    // Keyboard input.
    let input_tx = key_tx.clone();
    thread::spawn(move || loop {
        match event::read() {
            Ok(CEvent::Key(key)) => {
                if input_tx.send(Event::Input(key)).is_err() {
                    break;
                }
            }
            Ok(_) => {}
            Err(_) => break,
        }
    });

    // Redraw ticks.
    let tick_stop = Arc::new(AtomicBool::new(false));
    let tick_stop_thread = tick_stop.clone();
    let tick_tx = key_tx.clone();
    let tick_thread = thread::spawn(move || loop {
        thread::sleep(Duration::from_millis(250));
        if tick_stop_thread.load(Ordering::Acquire) || tick_tx.send(Event::Tick).is_err() {
            break;
        }
    });
    drop(key_tx);

    let mut stdout = io::stdout();
    enable_raw_mode()?;
    let (cols, rows) = crossterm::terminal::size()?;
    execute!(stdout, SetSize(cols, rows))?;
    if args.clear {
        execute!(stdout, EnterAlternateScreen)?;
    }
    let backend = TermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;
    terminal.clear()?;

    loop {
        match rx.recv()? {
            Event::Update(host_id, duration) => app.update(host_id, duration),
            Event::Input(key) => {
                if is_quit(&key) {
                    break;
                }
            }
            Event::Tick => {
                terminal.draw(|frame| {
                    render(frame, &app, args.vertical_margin, args.horizontal_margin)
                })?;
            }
            Event::Exit => break,
        }
    }

    kill_event.store(true, Ordering::Release);
    tick_stop.store(true, Ordering::Release);

    terminal.show_cursor()?;
    let size = terminal.size()?;
    terminal.set_cursor_position((size.width, size.height))?;
    if args.clear {
        execute!(io::stdout(), LeaveAlternateScreen)?;
    }
    disable_raw_mode()?;
    io::stdout().flush()?;
    let _ = tick_thread.join();

    Ok(())
}
