use std::str::FromStr;

use anyhow::{Context, Result};
use ratatui::style::Color;

/// Flatten the (possibly repeated, possibly comma separated) `--color` values
/// into one list of colour codes.
pub fn split_color_codes(values: &[String]) -> Vec<String> {
    values
        .iter()
        .flat_map(|value| value.split(','))
        .map(str::to_string)
        .collect()
}

/// The colour for the entry at `index`: the user supplied code if there is
/// one, otherwise a colour from the default palette.
pub fn color_for(codes: &[String], index: usize) -> Result<Color> {
    match codes.get(index) {
        Some(code) => {
            Color::from_str(code).with_context(|| format!("Invalid color code: `{}`", code))
        }
        None => Ok(default_color(index - codes.len())),
    }
}

/// The colour used for the `index`th entry without a user supplied colour.
fn default_color(index: usize) -> Color {
    Color::Indexed(((index + 2) % 256) as u8)
}
