//!
//! Widgets are rendered into an off-screen [`Buffer`]; on every frame only the
//! cells that changed since the previous frame are written to the terminal.

use std::cmp::max;
use std::io;

use ratatui::backend::{Backend, ClearType};
use ratatui::buffer::{Buffer, Cell};
use ratatui::layout::{Position, Rect, Size};
use unicode_width::UnicodeWidthStr;

pub struct Terminal<B: Backend> {
    backend: B,
    buffers: [Buffer; 2],
    current: usize,
    last_known_area: Rect,
}

impl<B: Backend<Error = io::Error>> Terminal<B> {
    pub fn new(backend: B) -> io::Result<Self> {
        let area = Rect::from((Position::ORIGIN, backend.size()?));
        Ok(Terminal {
            backend,
            buffers: [Buffer::empty(area), Buffer::empty(area)],
            current: 0,
            last_known_area: area,
        })
    }

    pub fn size(&self) -> io::Result<Size> {
        self.backend.size()
    }

    /// Pick up a changed terminal size: resize the buffers and clear the
    /// screen so the next frame is drawn from scratch.
    fn autoresize(&mut self) -> io::Result<()> {
        let area = Rect::from((Position::ORIGIN, self.backend.size()?));
        if area != self.last_known_area {
            self.buffers[self.current].resize(area);
            self.buffers[1 - self.current].resize(area);
            self.backend.clear_region(ClearType::All)?;
            self.buffers[1 - self.current].reset();
            self.last_known_area = area;
        }
        Ok(())
    }

    /// Render a frame using `render` and push the changes to the terminal.
    pub fn draw<F>(&mut self, render: F) -> io::Result<()>
    where
        F: FnOnce(Rect, &mut Buffer),
    {
        self.autoresize()?;
        let area = self.last_known_area;
        render(area, &mut self.buffers[self.current]);

        let updates = diff(&self.buffers[1 - self.current], &self.buffers[self.current]);
        self.backend.draw(updates.into_iter())?;
        self.backend.hide_cursor()?;

        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;

        self.backend.flush()
    }

    pub fn show_cursor(&mut self) -> io::Result<()> {
        self.backend.show_cursor()
    }

    pub fn set_cursor_position(&mut self, position: Position) -> io::Result<()> {
        self.backend.set_cursor_position(position)
    }
}

/// Work out which cells differ between two buffers of the same size, taking
/// multi-width symbols into account.
fn diff<'a>(previous: &Buffer, next: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
    let mut updates = Vec::new();
    // Cells invalidated by drawing/replacing preceding multi-width characters.
    let mut invalidated: usize = 0;
    // Cells to skip because a preceding multi-width character covers them.
    let mut to_skip: usize = 0;
    for (i, (current, prev)) in next.content.iter().zip(previous.content.iter()).enumerate() {
        if (current != prev || invalidated > 0) && to_skip == 0 {
            let (x, y) = next.pos_of(i);
            updates.push((x, y, current));
        }

        to_skip = current.symbol().width().saturating_sub(1);

        let affected_width = max(current.symbol().width(), prev.symbol().width());
        invalidated = max(affected_width, invalidated).saturating_sub(1);
    }
    updates
}
