/// Write `text` into the first row of `area`, truncated to the area's width,
/// and apply `style` to the whole area.
fn render_text(text: &str, area: Rect, style: Style, buf: &mut Buffer) {
    let area = area.intersection(*buf.area());
    if area.is_empty() {
        return;
    }
    buf.set_style(area, style);
    let y = area.y;
    let mut x = area.x;
    let mut remaining = area.width;
    for symbol in text.graphemes(true) {
        let width = symbol.width() as u16;
        if width == 0 {
            continue;
        }
        let Some(left) = remaining.checked_sub(width) else {
            break;
        };
        remaining = left;
        buf[(x, y)].set_symbol(symbol).set_style(style);
        let next = x + width;
        x += 1;
        // Cells hidden behind a multi-width symbol are blanked.
        while x < next {
            buf[(x, y)].reset();
            x += 1;
        }
    }
}
